<style>.footer-ai-trigger{height:40px;padding:0 15px;border:0;border-radius:8px;background:var(--primary);color:#fff;display:flex;align-items:center;gap:8px;font-weight:bold;cursor:pointer}.ai-float{position:fixed;right:22px;bottom:22px;z-index:1900;width:56px;height:56px;border:0;border-radius:50%;background:var(--primary-dark);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;box-shadow:0 12px 28px rgba(18,47,73,.24);cursor:pointer}.ai-float i{font-size:18px}.ai-float span{font-size:12px;font-weight:bold}.ai-chat-shell{position:fixed;right:22px;bottom:90px;z-index:2000;width:min(430px,calc(100vw - 28px));height:min(610px,calc(100vh - 120px));border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:0 22px 58px rgba(18,47,73,.22);overflow:hidden;display:flex;flex-direction:column;opacity:0;visibility:hidden;transform:translateY(12px);pointer-events:none;transition:.2s}.ai-chat-shell.open{opacity:1;visibility:visible;transform:none;pointer-events:auto}.ai-chat-head{min-height:62px;padding:0 14px;background:var(--primary-dark);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:10px}.ai-chat-head strong,.ai-chat-head span{display:block}.ai-chat-head strong{font-size:16px}.ai-chat-head span{margin-top:4px;font-size:13px;opacity:.8}.ai-chat-head button{width:34px;height:34px;border:0;border-radius:8px;background:rgba(255,255,255,.12);color:#fff;cursor:pointer}.ai-chat-messages{flex:1;padding:12px;overflow-y:auto;background:var(--soft-2);display:flex;flex-direction:column;gap:8px}.ai-message{max-width:90%;padding:10px 12px;border-radius:10px;font-size:14px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}.ai-message.model{align-self:flex-start;background:#fff;border:1px solid var(--line);color:var(--text)}.ai-message.user{align-self:flex-end;background:var(--primary);color:#fff}.ai-message.loading{color:var(--muted)}.ai-quick{padding:7px 10px;border-top:1px solid var(--lin