<script>
const overlay=document.querySelector('.js-overlay'),sidebar=document.querySelector('.js-mobile-sidebar'),toggleBtn=document.querySelector('.js-toggle-sidebar'),closeBtn=document.querySelector('.js-close-sidebar');function openMobileMenu(){if(!sidebar||!overlay)return;sidebar.classList.add('active');overlay.classList.add('active');document.body.style.overflow='hidden'}function closeMobileMenu(){if(!sidebar||!overlay)return;sidebar.classList.remove('active');overlay.classList.remove('active');document.body.style.overflow=''}if(toggleBtn)toggleBtn.addEventListener('click',openMobileMenu);if(closeBtn)closeBtn.addEventListener('click',closeMobileMenu);if(overlay)overlay.addEventListener('click',closeMobileMenu);document.querySelectorAll('.js-dropdown-toggle').forEach(function(button){button.addEventListener('click',function(event){event.stopPropagation();const item=button.closest('.action-item');document.querySelectorAll('.action-item.open').forEach(function(other){if(other!==item)other.classList.remove('open')});item.classList.toggle('open');button.setAttribute('aria-expanded',item.classList.contains('open')?'true':'false')})});document.addEventListener('click',function(event){document.querySelectorAll('.action-item.open').forEach(function(item){if(!item.contains(event.target)){item.classList.remove('open');const button=item.querySelector('.js-dropdown-toggle');if(button)button.setAttribute('aria-expanded','false')}})});function showCartNotice(status,message){if(window.Swal){Swal.fire({icon:status==='success'?'success':'error',title:status==='success'?'Đã thêm vào giỏ hàng':'Không thể thêm sản phẩm',text:message,confirmButtonText:'Đóng',confirmButtonColor:'#173f67',timer:status==='success'?1700:undefined,timerProgressBar:status==='success'});return}alert(message)}function refreshCartBadge(count){document.querySelectorAll('.badge').forEach(function(badge){badge.textContent=count});const dropdown=document.querySelector('.cart-dropdown');if(dropdown){dropdown.innerHTML='<div class="empty-mini-cart"><i class="fas fa-circle-check"></i><span>Giỏ hàng vừa được cập nhật</span></div><a class="mini-cart-button" href="<?php echo $base_url; ?>gio-hang">Xem giỏ hàng</a>'}}document.querySelectorAll('form[action*="add_to_cart.php"]').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();const button=form.querySelector('button[type="submit"]');const original=button?button.innerHTML:'';if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin"></i> Đang thêm...'}try{const data=new FormData(form);data.set('ajax','1');const response=await fetch(form.action,{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}});let result;try{result=await response.json()}catch(parseError){throw new Error('Phản hồi từ máy chủ không hợp lệ.')}if(!response.ok||result.status!=='success')throw new Error(result.message||'Không thể thêm sản phẩm vào giỏ hàng.');refreshCartBadge(result.cart_count);showCartNotice('success',result.message)}catch(error){showCartNotice('error',error.message||'Có lỗi xảy ra.')}finally{if(button){button.disabled=false;button.innerHTML=original}}})});<?php if($cart_flash): ?>showCartNotice(<?php echo json_encode($cart_flash['status'],JSON_UNESCAPED_UNICODE); ?>,<?php echo json_encode($cart_flash['message'],JSON_UNESCAPED_UNICODE); ?>);<?php endif; ?>
<?php if($chat_enabled):?>
const aiChat=document.querySelector('.js-ai-chat'),aiMessages=document.querySelector('.js-ai-messages'),aiForm=document.querySelector('.js-ai-form'),aiInput=document.querySelector('.js-ai-input');let aiHistory=[];function openAiChat(event){if(event)event.preventDefault();aiChat.classList.add('open');aiChat.setAttribute('aria-hidden','false');setTimeout(function(){aiInput.focus()},100)}function closeAiChat(){aiChat.classList.remove('open');aiChat.setAttribute('aria-hidden','true')}document.querySelectorAll('.js-open-ai').forEach(function(button){button.addEventListener('click',openAiChat)});document.querySelector('.js-close-ai').addEventListener('click',closeAiChat);function appendAiMessage(role,text,extraClass){const message=document.createElement('div');message.className='ai-message '+role+(extraClass?' '+extraClass:'');text=String(text||'').replace(/\*\*/g,'').replace(/__/g,'');message.textContent=text;aiMessages.appendChild(message);aiMessages.scrollTop=aiMessages.scrollHeight;return message}async function sendAiMessage(text){text=(text||'').trim();if(!text)return;appendAiMessage('user',text);const previous=aiHistory.slice(-8);aiHistory.push({role:'user',text:text});aiInput.value='';const loading=appendAiMessage('model','Gemini đang trả lời...','loading');try{const response=await fetch('<?php echo $base_url; ?>ai_chat.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,history:previous})});const data=await response.json();if(!response.ok||data.status!=='success')throw new Error(data.message||'Không thể nhận phản hồi từ AI');loading.remove();appendAiMessage('model',data.message);aiHistory.push({role:'model',text:data.message})}catch(error){loading.textContent=error.message||'Không thể kết nối Gemini AI.';loading.classList.remove('loading')}}aiForm.addEventListener('submit',function(event){event.preventDefault();sendAiMessage(aiInput.value)});document.querySelectorAll('.ai-quick button').forEach(function(button){button.addEventListener('click',function(){sendAiMessage(button.dataset.prompt)})});aiInput.addEventListener('keydown',function(event){if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();aiForm.requestSubmit()}});
<?php endif;?>
</script></body></html>
